  "Ranker": { src: "/photos/glossary/ranker.jpg", alt: "Illustration of Ranker matching the glossary definition.", caption: "Classroom diagram of Ranker \u2014 a labelled teaching graphic, not a field photograph. A thin soil over rock, often on a crest or steep slope. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "Recharge": { src: "/photos/glossary/recharge.jpg", alt: "Recharge: a matching field photograph or official scientific figure.", caption: "Recharge: a matching field photograph or official scientific figure. Water added to the aquifer, usually from rain and infiltration. Source: Wikimedia Commons / NASA / USGS / public domain.", credit: "Wikimedia Commons / NASA / USGS / public domain", kind: "photo" },
  "Regime": { src: "/photos/glossary/regime.jpg", alt: "Illustration of Regime matching the glossary definition.", caption: "Classroom diagram of Regime \u2014 a labelled teaching graphic, not a field photograph. Typical annual variation of discharge. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "Relief": { src: "/photos/glossary/relief.jpg", alt: "Illustration of Relief matching the glossary definition.", caption: "Classroom diagram of Relief \u2014 a labelled teaching graphic, not a field photograph. The difference in height across a landscape. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "Residence time": { src: "/photos/glossary/residence-time.jpg", alt: "Illustration of Residence time matching the glossary definition.", caption: "Classroom diagram of Residence time \u2014 a labelled teaching graphic, not a field photograph. It names the glossary sense of Residence time used on the TerraLens bench. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "Respiration": { src: "/photos/glossary/respiration.jpg", alt: "Illustration of Respiration matching the glossary definition.", caption: "Classroom diagram of Respiration \u2014 a labelled teaching graphic, not a field photograph. Fast flux from biosphere back to the atmosphere. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "Resurgence": { src: "/photos/glossary/resurgence.jpg", alt: "Resurgence: a matching photograph or official scientific figure.", caption: "Resurgence: a matching photograph or official scientific figure. Where underground drainage returns to the surface. Source: Wikimedia Commons / NASA / USGS / NPS, public domain or CC.", credit: "Wikimedia Commons / NASA / USGS / NPS, public domain or CC", kind: "photo" },
  "Reverse fault": { src: "/photos/glossary/reverse-fault.jpg", alt: "Reverse fault: a matching field photograph or official scientific figure.", caption: "Reverse fault: a matching field photograph or official scientific figure. Shortening. Source: Wikimedia Commons / NASA / USGS / public domain.", credit: "Wikimedia Commons / NASA / USGS / public domain", kind: "photo" },
  "Revolution": { src: "/photos/glossary/revolution.jpg", alt: "Illustration of Revolution matching the glossary definition.", caption: "Classroom diagram of Revolution \u2014 a labelled teaching graphic, not a field photograph. It names the glossary sense of Revolution used on the TerraLens bench. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "Rhumb line": { src: "/photos/glossary/rhumb-line.jpg", alt: "Illustration of Rhumb line matching the glossary definition.", caption: "Classroom diagram of Rhumb line \u2014 a labelled teaching graphic, not a field photograph. A path of constant bearing. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "Rift": { src: "/photos/glossary/rift.jpg", alt: "Rift: a matching field photograph or official scientific figure.", caption: "Rift: a matching field photograph or official scientific figure. A continent splitting. Source: Wikimedia Commons / NASA / USGS / public domain.", credit: "Wikimedia Commons / NASA / USGS / public domain", kind: "photo" },
  "Rill": { src: "/photos/glossary/rill.jpg", alt: "Rill: a matching photograph or official scientific figure.", caption: "Rill: a matching photograph or official scientific figure. Small erosional channel cut by running water. Source: Wikimedia Commons / NASA / USGS / NPS, public domain or CC.", credit: "Wikimedia Commons / NASA / USGS / NPS, public domain or CC", kind: "photo" },
  "Rising limb": { src: "/photos/glossary/rising-limb.jpg", alt: "Illustration of Rising limb matching the glossary definition.", caption: "Classroom diagram of Rising limb \u2014 a labelled teaching graphic, not a field photograph. The increase in discharge as the catchment starts to contribute. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "Root": { src: "/photos/glossary/root.jpg", alt: "Illustration of Root matching the glossary definition.", caption: "Classroom diagram of Root \u2014 a labelled teaching graphic, not a field photograph. Thick crust under a mountain, the submerged part of the raft. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "Rotation": { src: "/photos/glossary/rotation.jpg", alt: "Illustration of Rotation matching the glossary definition.", caption: "Classroom diagram of Rotation \u2014 a labelled teaching graphic, not a field photograph. It names the glossary sense of Rotation used on the TerraLens bench. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
