  "Run-up": { src: "/photos/glossary/run-up.jpg", alt: "Illustration of Run-up matching the glossary definition.", caption: "Classroom diagram of Run-up \u2014 a labelled teaching graphic, not a field photograph. How high the water reaches on land. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "S-wave": { src: "/photos/glossary/s-wave.jpg", alt: "Illustration of S-wave matching the glossary definition.", caption: "Classroom diagram of S-wave \u2014 a labelled teaching graphic, not a field photograph. Shear body wave. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "Saffir\u2013Simpson": { src: "/photos/glossary/saffir-simpson.jpg", alt: "Saffir\u2013Simpson: a matching field photograph or official scientific figure.", caption: "Saffir\u2013Simpson: a matching field photograph or official scientific figure. Wind-scale for tropical cyclones. Source: Wikimedia Commons / NASA / USGS / public domain.", credit: "Wikimedia Commons / NASA / USGS / public domain", kind: "photo" },
  "Salinity": { src: "/photos/glossary/salinity.jpg", alt: "Illustration of Salinity matching the glossary definition.", caption: "Classroom diagram of Salinity \u2014 a labelled teaching graphic, not a field photograph. Salt content. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
