  "Sand": { src: "/photos/glossary/sand.jpg", alt: "Illustration of Sand matching the glossary definition.", caption: "Classroom diagram of Sand \u2014 a labelled teaching graphic, not a field photograph. Coarsest of the three mineral sizes. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
