  "Sea breeze": { src: "/photos/glossary/sea-breeze.jpg", alt: "Sea breeze: a matching photograph or official scientific figure.", caption: "Sea breeze: a matching photograph or official scientific figure. Daytime onshore flow driven by land heating faster than the sea. Source: Wikimedia Commons / NASA / USGS / NPS, public domain or CC.", credit: "Wikimedia Commons / NASA / USGS / NPS, public domain or CC", kind: "photo" },
