  "Seamount": { src: "/photos/glossary/seamount.jpg", alt: "Seamount: a matching photograph or official scientific figure.", caption: "Seamount: a matching photograph or official scientific figure. Drowned volcano on the track. Source: Wikimedia Commons / NASA / USGS / NPS, public domain or CC.", credit: "Wikimedia Commons / NASA / USGS / NPS, public domain or CC", kind: "photo" },
  "Sediment budget": { src: "/photos/glossary/sediment-budget.jpg", alt: "Illustration of Sediment budget matching the glossary definition.", caption: "Classroom diagram of Sediment budget \u2014 a labelled teaching graphic, not a field photograph. Supply, transport, deposition, interruption. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
