  "Semi-diurnal tide": { src: "/photos/glossary/semi-diurnal-tide.jpg", alt: "Illustration of Semi-diurnal tide matching the glossary definition.", caption: "Classroom diagram of Semi-diurnal tide \u2014 a labelled teaching graphic, not a field photograph. Two highs and two lows in about a day, in the simple spinning-through-bulges picture. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
