  "Syncline": { src: "/photos/glossary/syncline.jpg", alt: "Syncline: a matching field photograph or official scientific figure.", caption: "Syncline: a matching field photograph or official scientific figure. A syncline is a down-fold: youngest beds in the core, limbs dipping in. Source: Wikimedia Commons / NASA / USGS / public domain.", credit: "Wikimedia Commons / NASA / USGS / public domain", kind: "photo" },
