  "Terrane": { src: "/photos/glossary/terrane.jpg", alt: "Illustration of Terrane matching the glossary definition.", caption: "Classroom diagram of Terrane \u2014 a labelled teaching graphic, not a field photograph. A crustal piece with its own history, later stitched on. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
