  "atmosphere-layers--mesosphere": { src: "/photos/terms/atmosphere-layers--mesosphere.jpg", alt: "Mesosphere in the atmosphere-layers lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Mesosphere \u2014 a labelled teaching graphic, not a field photograph. Layer above the stratosphere. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
