  "atmosphere-layers--troposphere": { src: "/photos/terms/atmosphere-layers--troposphere.jpg", alt: "Troposphere in the atmosphere-layers lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Troposphere in the atmosphere-layers lab \u2014 a TERMS crop, not the glossary plate and not the lab cover. Lowest layer. Source: Wikimedia Commons / NASA / USGS / public domain.", credit: "Wikimedia Commons / NASA / USGS / public domain", kind: "photo" },
  "carbon-cycle--fast-cycle": { src: "/photos/terms/carbon-cycle--fast-cycle.jpg", alt: "Fast cycle in the carbon-cycle lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Fast cycle \u2014 a labelled teaching graphic, not a field photograph. Atmosphere\u2013biosphere\u2013ocean exchanges on human timescales. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "carbon-cycle--flux": { src: "/photos/terms/carbon-cycle--flux.jpg", alt: "Flux in the carbon-cycle lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Flux \u2014 a labelled teaching graphic, not a field photograph. A transfer between stores. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "carbon-cycle--fossil-fuel": { src: "/photos/terms/carbon-cycle--fossil-fuel.jpg", alt: "Fossil fuel in the carbon-cycle lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Fossil fuel \u2014 a labelled teaching graphic, not a field photograph. A slow geologic store of carbon. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "carbon-cycle--photosynthesis": { src: "/photos/terms/carbon-cycle--photosynthesis.jpg", alt: "Photosynthesis in the carbon-cycle lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Photosynthesis \u2014 a labelled teaching graphic, not a field photograph. Fast flux from atmosphere into the biosphere. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
