  "climate-types--af": { src: "/photos/terms/climate-types--af.jpg", alt: "Af in the climate-types lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Af \u2014 a labelled teaching graphic, not a field photograph. Tropical rainforest. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "climate-types--biome": { src: "/photos/terms/climate-types--biome.jpg", alt: "Biome in the climate-types lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Biome in the climate-types lab \u2014 a TERMS crop, not the glossary plate and not the lab cover. A large-scale living landscape (rainforest, desert, tundra) written by climate plus more. Source: Wikimedia Commons / NASA / USGS / public domain.", credit: "Wikimedia Commons / NASA / USGS / public domain", kind: "photo" },
  "climate-types--bwh": { src: "/photos/terms/climate-types--bwh.jpg", alt: "BWh in the climate-types lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of BWh \u2014 a labelled teaching graphic, not a field photograph. Hot desert. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "climate-types--cfb": { src: "/photos/terms/climate-types--cfb.jpg", alt: "Cfb in the climate-types lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Cfb \u2014 a labelled teaching graphic, not a field photograph. Temperate, no dry season, warm summer. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "climate-types--climate": { src: "/photos/terms/climate-types--climate.jpg", alt: "Climate in the climate-types lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Climate \u2014 a labelled teaching graphic, not a field photograph. The longer pattern of temperature and rain. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
