  "climate-types--k-ppen": { src: "/photos/terms/climate-types--k-ppen.jpg", alt: "K\u00f6ppen in the climate-types lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "K\u00f6ppen in the climate-types lab \u2014 a TERMS crop, not the glossary plate and not the lab cover. A climate classification using temperature and precipitation, often mapped to biomes. Source: Wikimedia Commons / NASA / USGS / public domain.", credit: "Wikimedia Commons / NASA / USGS / public domain", kind: "photo" },
  "coasts--constructive-wave": { src: "/photos/terms/coasts--constructive-wave.jpg", alt: "Constructive wave in the coasts lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Constructive wave \u2014 a labelled teaching graphic, not a field photograph. Strong swash, weaker backwash. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
