  "coasts--sediment-budget": { src: "/photos/terms/coasts--sediment-budget.jpg", alt: "Sediment budget in the coasts lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Sediment budget \u2014 a labelled teaching graphic, not a field photograph. Supply, transport, deposition, interruption. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
