  "continental-drift--continental-drift": { src: "/photos/terms/continental-drift--continental-drift.jpg", alt: "Continental drift in the continental-drift lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Continental drift in the continental-drift lab \u2014 a TERMS crop, not the glossary plate and not the lab cover. Wegener\u2019s description of moving continents. Source: Wikimedia Commons / NASA / USGS / public domain.", credit: "Wikimedia Commons / NASA / USGS / public domain", kind: "photo" },
