  "continental-drift--supercontinent": { src: "/photos/terms/continental-drift--supercontinent.jpg", alt: "Supercontinent in the continental-drift lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Supercontinent \u2014 a labelled teaching graphic, not a field photograph. An assembly of most continents. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
