  "contours--spot-height": { src: "/photos/terms/contours--spot-height.jpg", alt: "Spot height in the contours lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Spot height \u2014 a labelled teaching graphic, not a field photograph. A surveyed point with a printed elevation. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
