  "cyclone-anticyclone--anticyclone": { src: "/photos/terms/cyclone-anticyclone--anticyclone.jpg", alt: "Anticyclone in the cyclone-anticyclone lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Anticyclone in the cyclone-anticyclone lab \u2014 a TERMS crop, not the glossary plate and not the lab cover. High-pressure system. Source: Wikimedia Commons / NASA / USGS / public domain.", credit: "Wikimedia Commons / NASA / USGS / public domain", kind: "photo" },
