  "cyclone-anticyclone--extra-tropical": { src: "/photos/terms/cyclone-anticyclone--extra-tropical.jpg", alt: "Extra-tropical in the cyclone-anticyclone lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Extra-tropical \u2014 a labelled teaching graphic, not a field photograph. Outside the tropics. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "drainage-basin--confluence": { src: "/photos/terms/drainage-basin--confluence.jpg", alt: "Confluence in the drainage-basin lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Confluence in the drainage-basin lab \u2014 a TERMS crop, not the glossary plate and not the lab cover. The meeting of two streams. Source: Wikimedia Commons / NASA / USGS / public domain.", credit: "Wikimedia Commons / NASA / USGS / public domain", kind: "photo" },
