  "earth-interior--crust": { src: "/photos/terms/earth-interior--crust.jpg", alt: "Crust in the earth-interior lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Crust in the earth-interior lab \u2014 a TERMS crop, not the glossary plate and not the lab cover. Rigid outer rock. Source: Wikimedia Commons / NASA / USGS / public domain.", credit: "Wikimedia Commons / NASA / USGS / public domain", kind: "photo" },
