  "earth-interior--p-wave": { src: "/photos/terms/earth-interior--p-wave.jpg", alt: "P-wave in the earth-interior lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of P-wave \u2014 a labelled teaching graphic, not a field photograph. Travels through solid and liquid. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "earth-interior--s-wave": { src: "/photos/terms/earth-interior--s-wave.jpg", alt: "S-wave in the earth-interior lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of S-wave \u2014 a labelled teaching graphic, not a field photograph. Travels through solids only. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "earthquakes--epicentre": { src: "/photos/terms/earthquakes--epicentre.jpg", alt: "Epicentre in the earthquakes lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Epicentre \u2014 a labelled teaching graphic, not a field photograph. Surface point vertically above the focus. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "earthquakes--focus": { src: "/photos/terms/earthquakes--focus.jpg", alt: "Focus in the earthquakes lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Focus in the earthquakes lab \u2014 a TERMS crop, not the glossary plate and not the lab cover. Where the slip starts in the rock. Source: Wikimedia Commons / NASA / USGS / public domain.", credit: "Wikimedia Commons / NASA / USGS / public domain", kind: "photo" },
  "earthquakes--intensity": { src: "/photos/terms/earthquakes--intensity.jpg", alt: "Intensity in the earthquakes lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Intensity \u2014 a labelled teaching graphic, not a field photograph. What a place feels, given distance, ground and buildings. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "earthquakes--magnitude": { src: "/photos/terms/earthquakes--magnitude.jpg", alt: "Magnitude in the earthquakes lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Magnitude \u2014 a labelled teaching graphic, not a field photograph. A scale for source size. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "earthquakes--p-wave": { src: "/photos/terms/earthquakes--p-wave.jpg", alt: "P-wave in the earthquakes lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of P-wave \u2014 a labelled teaching graphic, not a field photograph. Fastest body wave. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "earthquakes--s-wave": { src: "/photos/terms/earthquakes--s-wave.jpg", alt: "S-wave in the earthquakes lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of S-wave \u2014 a labelled teaching graphic, not a field photograph. Shear body wave. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
