  "eclipses--ecliptic": { src: "/photos/terms/eclipses--ecliptic.jpg", alt: "Ecliptic in the eclipses lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Ecliptic \u2014 a labelled teaching graphic, not a field photograph. The plane of Earth\u2019s orbit around the Sun. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
