  "energy-budget--emission": { src: "/photos/terms/energy-budget--emission.jpg", alt: "Emission in the energy-budget lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Emission \u2014 a labelled teaching graphic, not a field photograph. Radiation given out. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
