  "enso--la-ni-a": { src: "/photos/terms/enso--la-ni-a.jpg", alt: "La Ni\u00f1a in the enso lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of La Ni\u00f1a \u2014 a labelled teaching graphic, not a field photograph. Cool phase. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
