  "fronts--air-mass": { src: "/photos/terms/fronts--air-mass.jpg", alt: "Air mass in the fronts lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Air mass in the fronts lab \u2014 a TERMS crop, not the glossary plate and not the lab cover. A large body of air with fairly even temperature and humidity, sitting on a source region. Source: Wikimedia Commons / NASA / USGS / public domain.", credit: "Wikimedia Commons / NASA / USGS / public domain", kind: "photo" },
