  "geologic-time--cambrian": { src: "/photos/terms/geologic-time--cambrian.jpg", alt: "Cambrian in the geologic-time lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Cambrian \u2014 a labelled teaching graphic, not a field photograph. About 540 Ma. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
