  "geologic-time--k-pg": { src: "/photos/terms/geologic-time--k-pg.jpg", alt: "K\u2013Pg in the geologic-time lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of K\u2013Pg \u2014 a labelled teaching graphic, not a field photograph. About 66 Ma. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
