  "geologic-time--ma": { src: "/photos/terms/geologic-time--ma.jpg", alt: "Ma in the geologic-time lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Ma \u2014 a labelled teaching graphic, not a field photograph. Mega-annum: million years ago. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
