  "wilson-cycle--terrane": { src: "/photos/terms/wilson-cycle--terrane.jpg", alt: "Terrane in the wilson-cycle lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Terrane \u2014 a labelled teaching graphic, not a field photograph. A crustal piece with its own history, later stitched on. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "wilson-cycle--wilson-cycle": { src: "/photos/terms/wilson-cycle--wilson-cycle.jpg", alt: "Wilson cycle in the wilson-cycle lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Wilson cycle in the wilson-cycle lab \u2014 a TERMS crop, not the glossary plate and not the lab cover. The opening and closing of ocean basins, named for Tuzo Wilson. Source: Wikimedia Commons / NASA / USGS / public domain.", credit: "Wikimedia Commons / NASA / USGS / public domain", kind: "photo" },
  "wind--buys-ballot-s-law": { src: "/photos/terms/wind--buys-ballot-s-law.jpg", alt: "Buys Ballot\u2019s law in the wind lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Buys Ballot\u2019s law \u2014 a labelled teaching graphic, not a field photograph. In the northern hemisphere, with your back to the wind, low pressure is on the left. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "wind--coriolis": { src: "/photos/terms/wind--coriolis.jpg", alt: "Coriolis in the wind lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Coriolis \u2014 a labelled teaching graphic, not a field photograph. Apparent deflection because we measure on a rotating Earth. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "wind--friction": { src: "/photos/terms/wind--friction.jpg", alt: "Friction in the wind lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Friction \u2014 a labelled teaching graphic, not a field photograph. Surface drag that slows the wind, weakens Coriolis, and lets PGF pull across isobars toward low. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
  "wind--geostrophic-wind": { src: "/photos/terms/wind--geostrophic-wind.jpg", alt: "Geostrophic wind in the wind lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of Geostrophic wind \u2014 a labelled teaching graphic, not a field photograph. PGF balanced by Coriolis. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
