  "wind--pgf": { src: "/photos/terms/wind--pgf.jpg", alt: "PGF in the wind lab \u2014 a TERMS crop, not the glossary plate and not the lab cover.", caption: "Classroom diagram of PGF \u2014 a labelled teaching graphic, not a field photograph. Force from high to low pressure, downhill on the pressure surface. Source: TerraLens original diagram.", credit: "TerraLens classroom diagram", kind: "diagram" },
